param([Parameter(Mandatory=$true)][string]$MameRepository)
$ErrorActionPreference='Stop';$tag='mame0281';$expected='2843a3deb81cf93735244044894196ccfbea4d20'
$commit=(& git -C $MameRepository rev-parse "$tag^{commit}").Trim();if($LASTEXITCODE -ne 0 -or $commit -ne $expected){throw 'Unexpected MAME source tag'}
$files=@('src/devices/machine/6840ptm.cpp','src/devices/cpu/m6809/m6809.cpp','src/devices/cpu/m6809/m6809.h','src/devices/cpu/m6809/m6809.lst','src/devices/cpu/m6809/base6x09.lst','src/devices/cpu/m6809/m6809inl.h','src/mame/barcrest/mpu4.cpp','src/emu/schedule.cpp','src/emu/attotime.h','src/emu/diexec.cpp','src/frontend/mame/luaengine_mem.cpp')
$rows=@(foreach($path in $files){$blob=(& git -C $MameRepository rev-parse "$tag`:$path").Trim();if($LASTEXITCODE -ne 0){throw "Missing source $path"};$size=& git -C $MameRepository cat-file -s $blob;[ordered]@{path=$path;git_blob=$blob;bytes=[int]$size;url="https://github.com/mamedev/mame/blob/$commit/$path"}})
[ordered]@{classification='Pinned upstream release source references, not the original game source or proof of installed executable build provenance';local_repository=$MameRepository;tag=$tag;commit=$commit;files=$rows;irq_entry=[ordered]@{scope='Ordinary MC6809 IRQ at instruction completion, no higher-priority interrupt, not CWAI/SYNC';vector=65528;cycles=19;stack_bytes=12;saved_cc='CC|80';handler_cc='CC|90';frame_order='CC A B DP Xhi Xlo Yhi Ylo Uhi Ulo PChi PClo';source_symbols=@('MAIN','get_pending_interrupt','IRQ','PUSH_REGISTERS','INTERRUPT_VECTOR');implementation='src/FruitMachineLab.Runtime/M6809IrqEntry.cs';evidence='skill-cash/ptm-irq-entry.json'};selected_instruction_timing=[ordered]@{scope='Bounded opcode length/cycle decoder, not execution or a full ISA';source_symbols=@('MAIN','DIRECT','EXTENDED','INDEXED','LD16','ST8','PUSH_REGISTERS','PULL_REGISTERS','read_opcode');implementation='src/FruitMachineLab.Runtime/M6809InstructionTiming.cs';evidence='skill-cash/ptm-instruction-boundaries.json';qualification='Nineteen unmasked timer3 windows and their32-instruction native handler paths; other IRQ paths and generalized same-cycle ordering remain outside this evidence'};timer3_symbols=@('reload_counter','compute_counter','state_changed','update_expiration_for_clock_source');qualification='Source-guided rules remain checked against installed MAME captures; source assertion, input-line delivery, CPU acceptance and ROM handler service are separate stages.'}|ConvertTo-Json -Depth 6|Set-Content "$PSScriptRoot/../evidence/mpu4/maps/mame-timing-source.json"
Write-Output "Exported $($rows.Count) pinned source identities without changing MAME working files"
